Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": {
    "text": "Quanto de cada tipo saiu?",
    "subtitle": "% do plano do mês · vermelho = atrás do ritmo · clique no anel para filtrar",
    "anchor": "start",
    "font": "Segoe UI",
    "fontSize": 13,
    "fontWeight": 600,
    "color": "#3C3C3B",
    "subtitleFont": "Segoe UI",
    "subtitleFontSize": 10,
    "subtitleColor": "#8A8A88",
    "offset": 4
  },
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "filter": "datum[''HP Plano do Mês''] > 0"
    },
    {
      "calculate": "datum[''HP % do Plano''] < datum[''HP % Ritmo Esperado''] ? ''atrás'' : ''em dia''",
      "as": "situacao"
    },
    {
      "calculate": "replace(format(datum[''HP % do Plano''], ''.1%''), ''.'', '','')",
      "as": "pct1"
    },
    {
      "calculate": "format(datum[''HP % do Plano''], ''.0%'')",
      "as": "pct0"
    },
    {
      "calculate": "replace(format(datum[''HP % Ritmo Esperado''], ''.1%''), ''.'', '','')",
      "as": "ritmo1"
    },
    {
      "calculate": "replace(format(datum[''HP Plano do Mês''], '',.0f''), regexp('','', ''g''), ''.'')",
      "as": "plano1"
    },
    {
      "joinaggregate": [
        {
          "op": "max",
          "field": "HP Plano do Mês",
          "as": "pmax"
        }
      ]
    },
    {
      "calculate": "datum.pmax - datum[''HP Plano do Mês'']",
      "as": "chave"
    },
    {
      "calculate": "indexof([''1T'', ''1A'', ''2A'', ''4A''], datum[''Tipo'']) < 0 ? 9 : indexof([''1T'', ''1A'', ''2A'', ''4A''], datum[''Tipo''])",
      "as": "ordem"
    },
    {
      "calculate": "datum[''Tipo''] + ''  '' + replace(format(datum[''HP Plano do Mês''] / 1000, ''.1f''), ''.'', '','') + ''k''",
      "as": "rotulo"
    },
    {
      "calculate": "clamp(datum[''HP % do Plano''], 0, 1)",
      "as": "pct"
    }
  ],
  "facet": {
    "column": {
      "field": "Tipo",
      "type": "nominal",
      "sort": {
        "field": "ordem",
        "op": "min"
      },
      "title": null,
      "header": null
    }
  },
  "spacing": 10,
  "spec": {
    "width": 106,
    "height": 72,
    "layer": [
      {
        "mark": {
          "type": "arc",
          "innerRadius": 18,
          "outerRadius": 26,
          "color": "#E3E3E3"
        },
        "encoding": {
          "theta": {
            "datum": 1,
            "type": "quantitative",
            "scale": {
              "domain": [
                0,
                1
              ]
            }
          },
          "y": {
            "value": 28
          }
        }
      },
      {
        "mark": {
          "type": "arc",
          "innerRadius": 18,
          "outerRadius": 26
        },
        "encoding": {
          "theta": {
            "field": "pct",
            "type": "quantitative",
            "scale": {
              "domain": [
                0,
                1
              ]
            }
          },
          "y": {
            "value": 28
          },
          "color": {
            "field": "situacao",
            "type": "nominal",
            "scale": {
              "domain": [
                "atrás",
                "em dia"
              ],
              "range": [
                "#E2000F",
                "#3C3C3B"
              ]
            },
            "legend": null
          },
          "opacity": {
            "condition": {
              "test": "datum.__selected__ == ''off''",
              "value": 0.25
            },
            "value": 1
          }
        }
      },
      {
        "mark": {
          "type": "text",
          "font": "Segoe UI",
          "fontSize": 11,
          "fontWeight": "bold"
        },
        "encoding": {
          "y": {
            "value": 28
          },
          "text": {
            "field": "pct0"
          },
          "color": {
            "field": "situacao",
            "type": "nominal",
            "scale": {
              "domain": [
                "atrás",
                "em dia"
              ],
              "range": [
                "#E2000F",
                "#3C3C3B"
              ]
            },
            "legend": null
          }
        }
      },
      {
        "mark": {
          "type": "text",
          "font": "Segoe UI",
          "fontSize": 11,
          "color": "#3C3C3B"
        },
        "encoding": {
          "y": {
            "value": 64
          },
          "text": {
            "field": "rotulo"
          }
        }
      },
      {
        "params": [
          {
            "name": "__select__",
            "select": {
              "type": "point"
            }
          },
          {
            "name": "passa",
            "select": {
              "type": "point",
              "on": "pointerover",
              "clear": "pointerout"
            }
          }
        ],
        "mark": {
          "type": "rect",
          "cursor": "pointer",
          "cornerRadius": 6
        },
        "encoding": {
          "x": {
            "value": 0
          },
          "x2": {
            "value": "width"
          },
          "y": {
            "value": 0
          },
          "y2": {
            "value": "height"
          },
          "fill": {
            "condition": [
              {
                "param": "passa",
                "empty": false,
                "value": "rgba(60,60,59,0.08)"
              },
              {
                "test": "datum.__selected__ == ''on''",
                "value": "rgba(60,60,59,0.05)"
              }
            ],
            "value": "transparent"
          },
          "tooltip": [
            {
              "field": "Tipo",
              "title": "Tipo"
            },
            {
              "field": "plano1",
              "title": "Plano (m)"
            },
            {
              "field": "pct1",
              "title": "% do plano"
            },
            {
              "field": "ritmo1",
              "title": "Ritmo esperado"
            }
          ]
        }
      }
    ]
  },
  "config": {
    "view": {
      "stroke": null
    },
    "padding": {
      "left": 8,
      "right": 8,
      "top": 0,
      "bottom": 0
    }
  }
}'
